/**
 * 负责一个会话的复盘聚合、增量文件内容和终结发布；输入为事件、行动记录与结束元数据。
 * 输出为公开复盘、玩家视角和严格复现归档；聚合和存储仍由各自具体模块持有。
 * 生命周期模块唯一拥有定时器、队列、关闭与首次终结 Promise；本管理器保留必需失败账本。
 * 严格前缀写失败即登记，最终发布仍尝试完成；单个失败原样传播，多失败保持原顺序聚合。
 * 此处不控制游戏阶段或资源提交，不把可选诊断写入失败改成游戏错误。
 */
import type { Locale } from "@ai-werewolf-arena/game-text";
import { formatErrorDiagnostic } from "../utils/error_diagnostic";
import path from "path";
import type {
  DebugSummaryInput,
  ReplayFinalizeMeta,
  ReplayRecordDebugReportInput,
  ReplayRecordLogicOpInput,
  ReplayRecordPlayerEventInput,
  ReplayRecordPlayerRoundInput,
  ReplayRecordPublicEventInput,
  ReplaySessionMeta,
} from "./contracts";
import { currentRecordingIdentities, createPublicReplayArchive, createReproductionArchive, createManifestArchive, createPlayerViewArchive } from "./archive_identity";
import { createReplayDocument } from "./replay_document";
import { ReplayFileStore } from "./file_store";
import { ReplaySessionAggregate } from "./session_aggregate";
import { getSessionRecorder } from "./recording_context";
import { type ReproductionFailureScope, type ReproductionMetadata } from "./reproduction";
import { ReproductionTrace } from "./reproduction-trace";
import { SessionRecordingLifecycle } from "./session-recording-lifecycle";

/** 文件内容、严格失败及归档发布的唯一编排者；刷盘排程由具体生命周期实例持有。 */
export class SessionRecordManager {
  private readonly lifecycle = new SessionRecordingLifecycle(
    () => this.flushDirtyFiles(),
    (error) => {
      console.warn(
        `[observability] replay_flush_failed err=${formatErrorDiagnostic(error, this.displayLocale)}`,
      );
    },
  );
  private dirtyPublicTimeline = false;
  private dirtyLogicOps = false;
  private dirtyDebugReports = false;
  private readonly dirtyPlayers = new Set<number>();
  private reproduction?: ReproductionTrace;
  private dirtyReproduction = false;
  // 公开初始化档尚无严格来源；beginReproduction 后只捕获实际元数据，不向历史档补写当前身份。
  private recordingIdentities = currentRecordingIdentities();
  private replayEventCursor?: () => number;
  setReplayEventCursor(cursor: () => number): void {
    if (this.replayEventCursor || this.reproduction)
      throw Error("reproduction_event_cursor_already_bound");
    this.replayEventCursor = cursor;
  }
  get reproductionSettlementCount(): number {
    return this.reproduction?.settlementCount ?? 0;
  }
  get reproductionDecisionCount(): number {
    return this.reproduction?.decisionCount ?? 0;
  }
  private readonly mandatoryFlushFailures: unknown[] = [];

  private constructor(
    private readonly aggregate: ReplaySessionAggregate,
    private readonly store: ReplayFileStore,
    readonly displayLocale: Locale,
  ) {}

  static async create(
    sessionMeta: ReplaySessionMeta,
    recordRootDir: string,
    displayLocale: Locale = sessionMeta.locale ?? "zh-CN",
  ): Promise<SessionRecordManager> {
    const store = new ReplayFileStore(
      path.join(recordRootDir, sessionMeta.sessionId),
      displayLocale,
    );
    const manager = new SessionRecordManager(
      new ReplaySessionAggregate(sessionMeta),
      store,
      displayLocale,
    );
    await store.initialize();
    await manager.writeInitialFiles();
    return manager;
  }

  get sessionId(): string {
    return this.aggregate.sessionMeta.sessionId;
  }
  /** 严格复现实际序列化的领域操作数，不包含 AI 诊断操作。 */
  get reproductionOperationCount(): number {
    return this.aggregate.reproductionOperationCount;
  }
  get sessionDir(): string {
    return this.store.sessionDir;
  }

  beginReproduction(
    metadata: ReproductionMetadata,
    liveEvents?: () => readonly import("../core").GameEvent[],
  ): ReproductionTrace {
    if (this.lifecycle.isClosed || this.reproduction)
      throw new Error("reproduction_scope_already_started_or_closed");
    this.aggregate.enableReproduction();
    this.reproduction = new ReproductionTrace(
      metadata,
      () => {
        if (this.lifecycle.isClosed) return;
        this.dirtyReproduction = true;
        this.lifecycle.scheduleFlush();
      },
      liveEvents,
    );
    // 不以来源声明驱动新刷盘；下次原公开发布或最终发布自然携带已捕获身份。
    this.recordingIdentities = currentRecordingIdentities(this.reproduction.recordedMetadataIdentity());
    return this.reproduction;
  }

  noteReproductionFailure(scope: ReproductionFailureScope, error: unknown): void {
    this.reproduction?.noteFailure(scope, error);
  }

  recordPublicEvent(input: ReplayRecordPublicEventInput): void {
    if (this.lifecycle.isClosed) return;
    this.aggregate.recordPublicEvent(input);
    this.dirtyPublicTimeline = true;
    this.lifecycle.scheduleFlush();
  }

  /** 必需因果输入在 closing 起即拒绝；普通诊断仍保留原有的关闭前追加语义。 */
  recordRequiredLogicOp(input: ReplayRecordLogicOpInput): void {
    if (this.lifecycle.isClosed || this.lifecycle.isClosing)
      throw new Error("mandatory_logic_op_recording_closed");
    this.recordLogicOp(input);
  }

  recordLogicOp(input: ReplayRecordLogicOpInput): void {
    if (this.lifecycle.isClosed) return;
    const eventCount = this.reproduction?.ownedEventCursor ?? this.replayEventCursor?.();
    this.aggregate.recordLogicOp(eventCount === undefined ? input : { ...input, eventCount });
    this.dirtyLogicOps = true;
    this.lifecycle.scheduleFlush();
  }

  recordPlayerRound(input: ReplayRecordPlayerRoundInput): void {
    if (this.lifecycle.isClosed) return;
    this.aggregate.recordPlayerRound(input);
    this.dirtyPlayers.add(input.playerId);
    this.lifecycle.scheduleFlush();
  }

  recordPlayerEvent(input: ReplayRecordPlayerEventInput): void {
    if (this.lifecycle.isClosed) return;
    this.aggregate.recordPlayerEvent(input);
    this.dirtyPlayers.add(input.playerId);
    this.lifecycle.scheduleFlush();
  }

  recordDebugReport(input: ReplayRecordDebugReportInput): string {
    if (this.lifecycle.isClosed) return "rb-closed";
    const reportId = this.aggregate.recordDebugReport(input);
    this.dirtyDebugReports = true;
    this.lifecycle.scheduleFlush();
    return reportId;
  }

  flushNow(): Promise<void> {
    return this.lifecycle.flushNow();
  }

  finalize(meta: ReplayFinalizeMeta): Promise<DebugSummaryInput> {
    return this.lifecycle.finalize(() => this.persistFinalRecord(meta));
  }

  writeDebugSummary(markdown: string): Promise<void> {
    return this.store.writeText("debug_summary.md", markdown);
  }

  private async persistFinalRecord(meta: ReplayFinalizeMeta): Promise<DebugSummaryInput> {
    // closing 在首个 await 前生效；前缀完成后关闭追加，再发布最终文件。
    await this.lifecycle.beginClosing(meta);
    this.lifecycle.markClosed();

    const manifest = this.aggregate.buildManifest(meta);
    const replayDocument = this.buildReplayArchive(meta);
    const reproducible = () => {
      const input = this.aggregate.debugSummaryInput();
      const operations = (input.logicOps ?? [])
        .filter((op) => op.scope !== "llm_action_provider")
        .map(({ seq: _seq, timestamp: _timestamp, ...op }) => op);
      return this.reproduction!.build({
        operations,
        termination: { reason: meta.finishReason, winner: meta.winner },
      });
    };
    const required = await Promise.allSettled([
      this.store.writeJsonStrict("manifest.json", createManifestArchive(manifest, this.recordingIdentities)),
      this.store.writeJsonStrict("replay.json", replayDocument),
      ...(this.reproduction
        ? [
            Promise.resolve().then(() =>
              this.store.writeJsonStrict("reproduction.json", createReproductionArchive(reproducible())),
            ),
          ]
        : []),
    ]);
    await Promise.all([
      this.store.writeJson("phase_windows.json", this.aggregate.phaseWindowsPayload()),
      this.store.writeJson("timeline_index.json", this.aggregate.timelineIndexPayload()),
      this.store.writeJson("logic_ops.json", this.aggregate.logicOpsPayload()),
      this.store.writeJson("debug_reports.json", this.aggregate.debugReportsPayload()),
    ]);

    const playerViews = this.aggregate.normalizedPlayerViews();
    await Promise.all(
      playerViews.map((view) =>
        this.store.writeJson(`players/player_${view.player_id}.json`, createPlayerViewArchive(view, this.recordingIdentities)),
      ),
    );

    // 已失败的严格前缀先列出，再列本次必需终档失败；成功发布不撤销旧失败。
    const failures = [
      ...this.mandatoryFlushFailures,
      ...required
        .filter((result): result is PromiseRejectedResult => result.status === "rejected")
        .map((result) => result.reason),
    ];
    if (failures.length === 1) throw failures[0];
    if (failures.length) throw new AggregateError(failures, "session_record_finalization_failed");

    return {
      manifest,
      ...this.aggregate.debugSummaryInput(),
      sessionDir: this.sessionDir,
    };
  }

  private async writeInitialFiles(): Promise<void> {
    const results = await Promise.allSettled([
      this.store.writeJsonStrict("manifest.json", createManifestArchive(this.aggregate.buildManifest(), this.recordingIdentities)),
      this.store.writeJsonStrict("replay.json", this.buildReplayArchive()),
      this.store.writeJson("phase_windows.json", this.aggregate.phaseWindowsPayload()),
      this.store.writeJson("timeline_index.json", this.aggregate.timelineIndexPayload()),
      this.store.writeJson("logic_ops.json", this.aggregate.logicOpsPayload()),
      this.store.writeJson("debug_reports.json", this.aggregate.debugReportsPayload()),
    ]);
    const failures = results
      .filter((result): result is PromiseRejectedResult => result.status === "rejected")
      .map((result) => result.reason);
    if (failures.length === 1) throw failures[0];
    if (failures.length) throw new AggregateError(failures, "session_record_initialization_failed");
  }

  private async flushDirtyFiles(): Promise<void> {
    if (this.lifecycle.isClosed) return;
    if (this.dirtyReproduction && this.reproduction) {
      // 先消费本次脏位；严格失败登记在账本，后续仍可发布终档并报告此前失败。
      this.dirtyReproduction = false;
      try {
        await this.store.writeJsonStrict("reproduction.json", createReproductionArchive(this.reproduction.build()));
      } catch (error) {
        this.mandatoryFlushFailures.push(error);
        this.reproduction.noteFailure("recording", error);
        throw error;
      }
    }
    if (this.dirtyPublicTimeline) {
      this.dirtyPublicTimeline = false;
      await Promise.all([
        this.store.writeJson(
          "replay.json",
          this.buildReplayArchive(this.lifecycle.finalMetadata ?? undefined),
        ),
        this.store.writeJson("phase_windows.json", this.aggregate.phaseWindowsPayload()),
        this.store.writeJson("timeline_index.json", this.aggregate.timelineIndexPayload()),
      ]);
    }
    if (this.dirtyLogicOps) {
      this.dirtyLogicOps = false;
      await this.store.writeJson("logic_ops.json", this.aggregate.logicOpsPayload());
    }
    if (this.dirtyDebugReports) {
      this.dirtyDebugReports = false;
      await this.store.writeJson("debug_reports.json", this.aggregate.debugReportsPayload());
    }
    if (this.dirtyPlayers.size > 0) {
      const playerIds = [...this.dirtyPlayers];
      this.dirtyPlayers.clear();
      await Promise.all(
        playerIds.map(async (playerId) => {
          const view = this.aggregate.normalizedPlayerView(playerId);
          if (view) await this.store.writeJson(`players/player_${playerId}.json`, createPlayerViewArchive(view, this.recordingIdentities));
        }),
      );
      await Promise.all([
        this.store.writeJson(
          "manifest.json",
          createManifestArchive(this.aggregate.buildManifest(this.lifecycle.finalMetadata ?? undefined), this.recordingIdentities),
        ),
        this.store.writeJson("timeline_index.json", this.aggregate.timelineIndexPayload()),
      ]);
    }
  }

  private buildReplayArchive(meta?: ReplayFinalizeMeta) {
    return createPublicReplayArchive(createReplayDocument({
      manifest: this.aggregate.buildManifest(meta),
      events: this.aggregate.publicTimelinePayload().events,
    }), this.recordingIdentities);
  }
}

export function resolveDefaultRecordRoot(cwd: string = process.cwd()): string {
  return path.basename(cwd) === "backend"
    ? path.resolve(cwd, "..", "record")
    : path.resolve(cwd, "record");
}

export function buildSessionId(now: number = Date.now()): string {
  return `session_${now}_${Math.random().toString(36).slice(2, 8)}`;
}

export function safeRecordLogicOp(input: ReplayRecordLogicOpInput): void {
  const active = getSessionRecorder();
  if (!active) return;
  try {
    active.recordLogicOp(input);
  } catch (error) {
    console.warn(
      `[observability] logic_op_record_failed op=${input.op} err=${formatErrorDiagnostic(error, active.displayLocale)}`,
    );
  }
}

/**
 * 负责装配一局游戏、收缩绝对期限、关闭运行资源并汇总失败。
 * 输入为已解析的对局设置与本次执行依赖；输出为记录结果和可选审计摘要。
 * 请求别名与原体权限仍由机制所有者校验；本模块保留停止、关闭、等待与落盘的顺序，
 * 后续失败不回滚已提交的动作，也不把可选摘要失败升级为对局失败。
 * Agent 与复现记录共用本局板子来源；maxDays 在原元数据读取处捕获，循环复用该值。
 */
import { deriveBoundedRequest } from "../core/domain/request_delivery";
import {
  animalOriginalAuditIds,
  animalOriginalAuditPlayer,
} from "../game/mechanisms/roles/animal_dream/roster";
import { aliveLifeDescriptor } from "../core/domain/components/alive";
import { initialPlayerIdentity } from "../core/domain/initial_roster";
import { initialIdentityDeal } from "../game/mechanisms/roles/initial_identity/deal";
import { text } from "@ai-werewolf-arena/game-text";
import { formatErrorDiagnostic } from "../utils/error_diagnostic";
/** 本局资源、期限、失败汇总与最终复盘由下方 runner 持有；导入不装配对局。 */
import path from "node:path";
import { bootstrapGame } from "../app/bootstrap";
import {
  COMPONENT,
  type ActionProvider,
  type ActionRequest,
  type AliveComponent,
  type RoleComponent,
  type RuntimeSnapshot,
  type ToolCall,
  type World,
  type IdentityComponent,
  createRandom,
} from "../core";
import type { ResolvedAgentRuntimeProfile } from "./config/contracts";
import type { ResolvedGameSetup } from "./config/resolve_game_setup";
import { resolvePlayerProfile } from "./config/resolve_game_setup";
import {
  createAcpConsoleLogger,
  createConsoleLog,
  presentGameResult,
  presentStreamEvents,
} from "./console_presenter";
import { GameEventRecorder } from "./game_event_recorder";
import {
  buildSessionId,
  resolveDefaultRecordRoot,
  SessionRecordManager,
} from "../recording/session_recorder";
import { runWithSessionRecorder } from "../recording/recording_context";
import { buildDebugSummaryMarkdown } from "../audit/debug_summary_generator";
import { createPlayerAgentRuntime, type PlayerAgentRuntime } from "./player_agent_factory";
import {
  beginGameReproduction,
  captureCheckpoint,
  currentEngineVersion,
} from "./simulation/reproduction_context";

/** 仅返回最终运行快照与领域事件总数；完整回放由会话记录器持久化。 */
export interface GameRunResult {
  snapshot: RuntimeSnapshot;
  eventCount: number;
}
/**
 * 每局独立的执行依赖，不进入玩家 DTO 或 JSON 配置。
 * 期限选择回调返回绝对时间，只参与取最小值；关闭观察回调接收脱离副本，异常归清理失败。
 */
export interface GameRunDependencies {
  selectRequestDeadline?: (
    request: Readonly<{
      actorId: number;
      day: number;
      stage: ActionRequest["context"]["stage"];
      ordinal: number;
      actorOrdinal: number;
      retryAttempt: number;
      nowMs: number;
    }>,
  ) => number | undefined;
  onRuntimeClosed?: (state: PlayerAgentRuntime["runtimeState"]) => void;
}

class DeadlineAwareActionProvider implements ActionProvider {
  private ordinal = 0;
  private readonly actors = new Map<number, number>();
  // 同一玩家／日期／stage 的重试沿用已记录预算；新尝试仍受全局与原请求期限限制。
  private readonly budgets = new Map<string, number>();
  constructor(
    private readonly delegate: ActionProvider,
    private readonly deadlineAtMs: number,
    private readonly timeoutMs: number,
    private readonly selectDeadline?: GameRunDependencies["selectRequestDeadline"],
  ) {}

  getAction(request: ActionRequest): Promise<ToolCall | null> {
    const nowMs = Date.now(),
      actorOrdinal = (this.actors.get(request.actorId) ?? 0) + 1;
    this.actors.set(request.actorId, actorOrdinal);
    const ordinal = ++this.ordinal;
    const retryAttempt = request.context.retry_attempt ?? 0;
    const selected = this.selectDeadline?.({
      actorId: request.actorId,
      day: request.context.day,
      stage: request.context.stage,
      ordinal,
      actorOrdinal,
      retryAttempt,
      nowMs,
    });
    if (selected !== undefined && !Number.isFinite(selected))
      throw new RangeError("game_request_deadline_invalid");
    const key = `${request.actorId}/${request.context.day}/${request.context.stage}`;
    // 期限只取最早绝对时间，重试不重置整份超时；运行时授权随原请求一起派生。
    const deadline = Math.min(
      this.deadlineAtMs,
      request.deadlineAtMs ?? Infinity,
      nowMs + this.timeoutMs,
      selected ?? Infinity,
      retryAttempt > 0 ? (this.budgets.get(key) ?? Infinity) : Infinity,
    );
    this.budgets.set(key, deadline);
    const timed = deriveBoundedRequest(request, deadline);
    return this.delegate.getAction(timed);
  }
}

/** 调用方先完成设置解析；这里装配并执行对局，不读取配置来源文件。 */
export async function runGame(
  setup: ResolvedGameSetup,
  dependencies: GameRunDependencies = {},
): Promise<GameRunResult> {
  const context = bootstrapGame(setup.boardConfig, {
    random: createRandom(setup.context.seed),
    locale: setup.context.locale,
    playerNames: Object.fromEntries(
      Object.entries(setup.players).flatMap(([seat, entry]) =>
        entry.name !== undefined ? [[seat, entry.name]] : [],
      ),
    ),
  });
  const profilesByActor = selectPlayerProfiles(context.world, setup);
  const sessionId = buildSessionId();
  const recordRoot = setup.options.recordRootDir ?? resolveDefaultRecordRoot();
  const replayManager = await SessionRecordManager.create(
    {
      sessionId,
      locale: setup.context.locale,
      board: setup.options.board,
      startedAtIso: new Date().toISOString(),
      random: context.random.metadata,
    },
    recordRoot,
    setup.context.displayLocale,
  );

  return runWithSessionRecorder(replayManager, async () => {
    const { options } = setup;
    const log = createConsoleLog(options.color);
    const startedAt = Date.now();
    const deadlineAtMs = startedAt + options.maxRuntimeMs;
    // 对局／记录失败统一汇总；并发动作和关闭失败暂存，收尾时按原顺序补入。
    const failures: unknown[] = [];
    const eventRecorder = new GameEventRecorder(
      {
        world: context.world,
        replayManager,
      },
      context.phaseManager.getSnapshot().phase,
    );
    const flushEvents = () => {
      const delta = eventRecorder.flush(context.phaseManager.getEvents());
      if (options.streamEvents)
        presentStreamEvents(delta, options.printPrivateEvents, log, setup.context.displayLocale);
    };
    let agentRuntime: PlayerAgentRuntime | undefined;
    let heartbeat: NodeJS.Timeout | undefined;
    let streamTimer: NodeJS.Timeout | undefined;
    let timedOut = false;
    // stopping 立即拒绝新动作和迟到回复；closing 合并关闭调用，inFlight 单独负责等待结算。
    let stopping = false;
    let closing: Promise<void> | undefined;
    const stopReason = new DOMException("game_actions_stopped", "AbortError");
    const inFlight = new Set<Promise<ToolCall | null>>();
    const actionFailures: unknown[] = [];
    const cleanupFailures: unknown[] = [];
    let maxDays: number;
    // 先撤运行入口，再异步关闭 Agent；关闭异常暂存，不能覆盖触发停止的原始失败。
    const closeRuntime = (): Promise<void> => {
      stopping = true;
      closing ??= Promise.resolve()
        .then(() => agentRuntime?.close())
        .catch((error) => {
          cleanupFailures.push(error);
        });
      return closing;
    };
    const drainActions = async () => {
      while (inFlight.size) await Promise.allSettled([...inFlight]);
    };

    try {
      const reproduction = beginGameReproduction(replayManager, context, {
        engine: await currentEngineVersion(),
        boardId: options.board,
        locale: context.world.locale,
        maxDays: (maxDays = options.maxDays),
        profiles: profilesByActor,
      });
      agentRuntime = await createPlayerAgentRuntime({
        world: context.world,
        boardConfig: context.boardConfig,
        profilesByActor,
        acpWorkspaceRoot: path.join(recordRoot, sessionId, "acp-workspaces"),
        llmTimeoutMs: options.llmTimeoutMs,
        trace: options.trace,
        displayLocale: setup.context.displayLocale,
        colorizeLogs: options.color,
        printLlmIo: options.printLlmIo,
        printThinking: options.printThinking,
        createAcpUpdateObserver:
          options.printThinking || options.printLlmIo
            ? (actorId) =>
                createAcpConsoleLogger(actorId, log, setup.context.displayLocale, {
                  printThinking: options.printThinking,
                  printLlmIo: options.printLlmIo,
                })
            : undefined,
      });
      const selectedProvider: ActionProvider = {
        async getAction(request) {
          if (stopping) throw stopReason;
          const action = await agentRuntime!.provider.getAction(request);
          if (stopping) throw stopReason;
          return action;
        },
      };
      const decisionProvider: ActionProvider = {
        getAction: (request) => {
          const decision = reproduction.decide(request, selectedProvider);
          let tracked!: Promise<ToolCall | null>;
          tracked = decision.then(
            (action) => {
              inFlight.delete(tracked);
              return action;
            },
            (error) => {
              inFlight.delete(tracked);
              if (error !== stopReason) actionFailures.push(error);
              // 保留记录器已写的决策前缀，再开始取消其它动作，保留原异常的因果先后。
              void closeRuntime();
              throw error;
            },
          );
          inFlight.add(tracked);
          return tracked;
        },
      };
      const provider = new DeadlineAwareActionProvider(
        decisionProvider,
        deadlineAtMs,
        options.llmTimeoutMs,
        dependencies.selectRequestDeadline,
      );
      log(
        `[run_game] start board=${options.board} replay_session_id=${sessionId} record_dir=${replayManager.sessionDir} · ${text(setup.context.displayLocale, "runtime.start")}`,
        "info",
      );

      if (options.trace) {
        heartbeat = setInterval(() => {
          const snapshot = context.phaseManager.getSnapshot();
          log(
            `[run_game] heartbeat day=${snapshot.day} phase=${snapshot.phase} gameOver=${snapshot.gameOver} elapsed_ms=${Date.now() - startedAt} · ${text(setup.context.displayLocale, "runtime.heartbeat")}`,
            "muted",
          );
        }, 5000);
      }
      streamTimer = setInterval(() => {
        try {
          flushEvents();
        } catch (error) {
          failures.push(error);
          replayManager.noteReproductionFailure("recording", error);
          void closeRuntime();
          if (streamTimer) clearInterval(streamTimer);
        }
      }, 1000);

      let cycle = 0;
      while (!context.phaseManager.getSnapshot().gameOver && failures.length === 0) {
        const elapsed = Date.now() - startedAt;
        if (elapsed >= options.maxRuntimeMs) {
          timedOut = true;
          log(
            `[run_game] runtime_timeout elapsed_ms=${elapsed} · ${text(setup.context.displayLocale, "runtime.timeout")}`,
            "warn",
          );
          break;
        }
        cycle++;
        let complete = false;
        let cycleFailure: unknown;
        try {
          await context.phaseManager.runSingleCycle(provider, maxDays);
          complete = true;
        } catch (error) {
          cycleFailure = error;
          if (error !== stopReason) failures.push(error);
          replayManager.noteReproductionFailure("cycle", error);
          await closeRuntime();
          await drainActions();
        }
        // 无论周期成功或失败都保存实际结算前缀；失败周期先关闭并等待已在途动作。
        try {
          reproduction.checkpoint(
            captureCheckpoint(
              context.world,
              context.phaseManager.getSnapshot(),
              cycle,
              complete,
              context.phaseManager.getEvents().length,
              cycleFailure,
            ),
            context.phaseManager.getEvents(),
          );
        } catch (error) {
          failures.push(error);
          reproduction.invalidate();
          replayManager.noteReproductionFailure("recording", error);
        }
        if (failures.length) break;
        const snapshot = context.phaseManager.getSnapshot();
        log(
          `[run_game] cycle day=${snapshot.day} phase=${snapshot.phase} gameOver=${snapshot.gameOver} elapsed_ms=${Date.now() - startedAt} · ${text(setup.context.displayLocale, "runtime.cycle")}`,
          "info",
        );
      }
    } catch (error) {
      failures.push(error);
      replayManager.noteReproductionFailure("initialization", error);
    } finally {
      // 先停定时任务并补事件，再关闭／等待动作；最终记录只在这些原收尾步骤之后发布。
      if (heartbeat) clearInterval(heartbeat);
      if (streamTimer) clearInterval(streamTimer);
      try {
        flushEvents();
      } catch (error) {
        failures.push(error);
        replayManager.noteReproductionFailure("recording", error);
      }
      await closeRuntime();
      await drainActions();
      if (agentRuntime && dependencies.onRuntimeClosed) {
        try {
          dependencies.onRuntimeClosed(structuredClone(agentRuntime.runtimeState));
        } catch (error) {
          cleanupFailures.push(error);
        }
      }
      // 取消标记不列为独立动作错误；原异常按引用去重，清理失败仍按发生顺序追加。
      for (const error of actionFailures)
        if (!failures.includes(error)) {
          failures.push(error);
          replayManager.noteReproductionFailure("controller", error);
        }
      for (const error of cleanupFailures) {
        failures.push(error);
        replayManager.noteReproductionFailure("cleanup", error);
      }
      try {
        const snapshot = context.phaseManager.getSnapshot();
        const summaryInput = await replayManager.finalize({
          endedAtIso: new Date().toISOString(),
          winner: snapshot.result?.winner ?? null,
          ...(snapshot.result ? { gameResult: snapshot.result } : {}),
          finishReason: failures.length
            ? "runtime_error"
            : (snapshot.result?.reason ?? (timedOut ? "runtime_timeout" : "completed")),
          players: replayPlayers(context.world),
        });
        // 核心终档失败进入汇总；诊断摘要为可选输出，其异常只写日志。
        try {
          await replayManager.writeDebugSummary(
            await buildDebugSummaryMarkdown(
              {
                ...summaryInput,
                locale: setup.context.locale,
                displayLocale: setup.context.displayLocale,
              },
              setup.audit,
            ),
          );
        } catch (error) {
          log(
            `[audit] debug_summary_failed err=${formatErrorDiagnostic(error, setup.context.displayLocale)}`,
            "warn",
          );
        }
      } catch (error) {
        failures.push(error);
      }
    }

    if (failures.length === 1) throw failures[0];
    if (failures.length > 1) throw new AggregateError(failures, "game_run_failed");
    const snapshot = context.phaseManager.getSnapshot();
    const events = context.phaseManager.getEvents();
    presentGameResult({
      locale: setup.context.displayLocale,
      board: options.board,
      snapshot,
      events,
      timedOut,
      printAllEvents: options.printAllEvents,
      printChat: options.printChat,
      streamEvents: options.streamEvents,
      log,
    });
    return { snapshot, eventCount: events.length };
  });
}

function selectPlayerProfiles(
  world: World,
  setup: ResolvedGameSetup,
): Map<number, ResolvedAgentRuntimeProfile> {
  const profiles = new Map<number, ResolvedAgentRuntimeProfile>();
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role)?.role;
    profiles.set(id, resolvePlayerProfile(setup, id, role));
  }
  return profiles;
}

/**
 * 构造 God 终档的身份记录，不复用玩家观察视图。
 * 动物梦境读取已捕获的原名单／身份与原生命；初始身份机制保留原发牌，普通局使用当前组件。
 */
function replayPlayers(world: World) {
  const originalIds = animalOriginalAuditIds(world);
  if (originalIds)
    return originalIds.map((id) => {
      const original = animalOriginalAuditPlayer(world, id)!,
        identity = JSON.parse(original.identityJson);
      return {
        player_id: id,
        role: original.scope.roleId,
        camp: original.scope.campValue,
        alive: aliveLifeDescriptor(original.scope.life)!.get!.call(original.scope.life),
        name: identity.name,
      };
    });
  const initial = initialIdentityDeal(world);
  return world.entityIds().map((id, index) => {
    const role = world.getComponent(id, COMPONENT.Role);
    return {
      player_id: id,
      role: initialPlayerIdentity(world, id)?.role ?? initial?.[index] ?? role?.role ?? "unknown",
      camp:
        initialPlayerIdentity(world, id)?.camp ??
        (initial ? (initial[index] === "wolf" ? "wolf" : "good") : (role?.camp ?? "unknown")),
      alive: world.getComponent(id, COMPONENT.Alive)?.alive === true,
      name: world.getComponent(id, COMPONENT.Identity)?.name,
    };
  });
}
